import { BookingService } from './booking.service';
import { CalendarService } from './calendar.service';
import {
  id,
  reason,
  target,
  period,
  evaluation,
  create,
  change,
  assignVehicle,
  cancelBooking,
} from './booking.dto';
import type { Calculation } from '../pricing/calculate';
import { Body, Controller, Get, Param, Patch, Post, Query, Req } from '@nestjs/common';
import { z } from 'zod';
import { AuthRequest, audit, fail, idSchema, parse } from '../platform/security';
import { SchedulingService, scheduleLock } from './scheduling.service';
import { bookingPricing, previewBooking } from './booking-pricing';
import { isDeepStrictEqual } from 'node:util';
import type { PoolClient } from 'pg';
const version = z.object({ expectedVersion: id, reason }).strict();
const moveInput = z
  .object({
    startAt: z.iso.datetime({ offset: true }),
    vehicleId: id,
    expectedVersion: id,
    availabilityToken: z.string().regex(/^[a-f0-9]{64}$/),
    quoteToken: z.string().optional(),
    reason: z.string().trim().min(1).max(1000).default('Изменение автомобиля или времени брони'),
  })
  .strict();
const technicalInput = z
  .object({
    vehicleId: id,
    ...period,
    reason,
    conflictsToken: z.string().optional(),
    displaceBookings: z.array(z.object({ id, expectedVersion: id }).strict()).optional(),
    expectedVersion: id.optional(),
  })
  .strict()
  .refine((v) => Date.parse(v.endAt) > Date.parse(v.startAt), 'Период должен быть непустым.');
@Controller()
export class SchedulingController {
  constructor(
    private readonly s: SchedulingService,
    private readonly bookings: BookingService,
    private readonly calendarService: CalendarService,
  ) {}
  @Get('booking-customers') async customers(@Query() raw: unknown) {
    const { q } = parse(z.object({ q: z.string().trim().max(250) }).strict(), raw);
    if (q.length < 2) return { items: [] };
    return {
      items: (
        await this.s.db.pool.query(
          `SELECT id,type,display_name AS "displayName",phone,is_blocked AS "isBlocked" FROM customers WHERE strpos(lower(display_name),lower($1))>0 OR ($2<>'' AND strpos(regexp_replace(phone,'[^0-9]','','g'),$2)>0) OR strpos(inn,$1)>0 ORDER BY lower(display_name),id LIMIT 20`,
          [q, q.replace(/\D/g, '')],
        )
      ).rows,
    };
  }
  @Get('booking-options') async options() {
    return this.s.db.transaction(async (c) => {
      await c.query('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');
      const vehicles = (
        await c.query(
          `SELECT v.id,v.model_id AS "modelId",m.brand_id AS "brandId",m.name AS "modelName",v.plate,b.name||' '||m.name||' · '||v.plate AS label,v.is_ready AS "isReady",v.readiness_reason AS "readinessReason" FROM vehicles v JOIN vehicle_models m ON m.id=v.model_id JOIN vehicle_brands b ON b.id=m.brand_id WHERE v.archived_at IS NULL ORDER BY b.name,m.name,v.plate`,
        )
      ).rows;
      const models = (
        await c.query(
          `SELECT m.id,m.brand_id AS "brandId",m.pricing_group_id AS "pricingGroupId",b.name||' '||m.name AS label FROM vehicle_models m JOIN vehicle_brands b ON b.id=m.brand_id ORDER BY b.name,m.name`,
        )
      ).rows;
      const brands = (await c.query('SELECT id,name AS label FROM vehicle_brands ORDER BY name'))
        .rows;
      const groups = (
        await c.query('SELECT id,name AS label FROM equivalence_groups ORDER BY name')
      ).rows;
      return { vehicles, models, brands, groups };
    });
  }
  @Post('bookings/preview') async preview(@Body() raw: unknown, @Req() request: AuthRequest) {
    const input = parse(
      z.object({ target, pricing: bookingPricing, bookingId: id.optional() }).strict(),
      raw,
    );
    return this.s.db.transaction(async (c) => {
      await c.query('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');
      const old = input.bookingId
        ? (await c.query('SELECT * FROM bookings WHERE id=$1', [input.bookingId])).rows[0]
        : undefined;
      if (input.bookingId && !old) fail(404, 'NOT_FOUND', 'Бронь не найдена.');
      const same =
        old &&
        old.target_type === input.target.type &&
        (old.target_vehicle_id ??
          old.target_model_id ??
          old.target_brand_id ??
          old.target_group_id) === input.target.id;
      const models = same
        ? (
            await c.query(
              'SELECT model_id FROM booking_eligible_models WHERE booking_id=$1 ORDER BY model_id',
              [old.id],
            )
          ).rows.map((x) => x.model_id)
        : await this.s.models(c, input.target);
      const preview = await previewBooking(
        c,
        input.target,
        input.pricing,
        models,
        request.auth!.user.id,
      );
      const inspection = await this.s.inspect(c, {
        id: input.bookingId,
        target: input.target,
        models,
        startAt: preview.calculation.startAt,
        endAt: preview.calculation.agreedReturnAt,
        vehicleId: input.target.type === 'vehicle' ? input.target.id : null,
      });
      return { ...preview, ...inspection };
    });
  }
  @Get('vehicles/:id/schedule')
  async vehicleSchedule(
    @Param('id')
    raw: string,
  ) {
    return {
      items: (
        await this.s.db.pool.query(
          "SELECT * FROM schedule_blocks WHERE vehicle_id=$1 AND kind='technical' AND retired_at IS NULL ORDER BY start_at",
          [parse(idSchema, raw)],
        )
      ).rows,
    };
  }
  @Get('calendar')
  async calendar(
    @Query()
    raw: unknown,
  ) {
    const q = parse(
      z
        .object({ from: z.iso.datetime({ offset: true }), to: z.iso.datetime({ offset: true }) })
        .strict()
        .refine(
          (v) =>
            Date.parse(v.to) > Date.parse(v.from) &&
            Date.parse(v.to) - Date.parse(v.from) <= 93 * 86400000,
        ),
      raw,
    );
    return this.calendarService.get(q);
  }
  @Post('schedule-blocks/preview')
  async previewTechnical(@Body() raw: unknown) {
    const input = parse(
      z
        .object({ vehicleId: id, ...period, blockId: id.optional() })
        .strict()
        .refine((v) => Date.parse(v.endAt) > Date.parse(v.startAt)),
      raw,
    );
    return this.s.db.transaction(async (c) => {
      await c.query('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');
      return this.s.technicalPreview(c, input);
    });
  }
  @Post('schedule-blocks')
  technical(@Body() raw: unknown, @Req() r: AuthRequest) {
    return this.saveTechnical(parse(technicalInput, raw), r);
  }
  @Patch('schedule-blocks/:id')
  updateTechnical(@Param('id') raw: string, @Body() body: unknown, @Req() r: AuthRequest) {
    return this.saveTechnical(parse(technicalInput, body), r, parse(idSchema, raw));
  }
  private saveTechnical(input: z.infer<typeof technicalInput>, r: AuthRequest, blockId?: number) {
    return this.s.commands.run(
      r,
      blockId ? 'schedule.update' : 'schedule.create',
      { blockId, ...input },
      async (c) => {
        await scheduleLock(c);
        if (blockId) {
          const old = (
            await c.query(
              "SELECT * FROM schedule_blocks WHERE id=$1 AND kind='technical' AND retired_at IS NULL FOR UPDATE",
              [blockId],
            )
          ).rows[0];
          if (!old || old.version !== input.expectedVersion || old.vehicle_id !== input.vehicleId)
            fail(409, 'VERSION_CONFLICT', 'Блокировка изменилась. Перечитайте данные.');
        }
        const preview = await this.s.technicalPreview(c, {
          vehicleId: input.vehicleId,
          startAt: input.startAt,
          endAt: input.endAt,
          ...(blockId ? { blockId } : {}),
        });
        if (preview.conflicts.some((x) => x.kind === 'technical'))
          fail(
            409,
            'TECHNICAL_BLOCK_CONFLICT',
            'Период пересекается с технической блокировкой. Измените существующую блокировку.',
            preview,
          );
        const affected = preview.conflicts.filter((x) => x.booking_id);
        const expected = affected
          .map((x) => ({ id: x.booking_id, expectedVersion: x.booking_version }))
          .sort((a, b) => a.id - b.id);
        const accepted = [...(input.displaceBookings ?? [])].sort((a, b) => a.id - b.id);
        if (
          affected.length &&
          (input.conflictsToken !== preview.token || !isDeepStrictEqual(expected, accepted))
        )
          fail(
            409,
            'TECHNICAL_BOOKINGS_CONFIRMATION_REQUIRED',
            'Подтвердите снятие назначений со всех затронутых броней.',
            preview,
          );
        if (!affected.length && accepted.length)
          fail(
            409,
            'TECHNICAL_PREVIEW_STALE',
            'Состав затронутых броней изменился. Проверьте период снова.',
            preview,
          );
        for (const conflict of affected) {
          const b = (
            await c.query('SELECT * FROM bookings WHERE id=$1 FOR UPDATE', [conflict.booking_id])
          ).rows[0];
          if (!b || b.version !== conflict.booking_version || b.status !== 'confirmed')
            fail(409, 'BOOKING_VERSION_CONFLICT', 'Затронутая бронь изменилась.');
          await c.query(
            'UPDATE schedule_blocks SET retired_at=now(),version=version+1 WHERE id=$1',
            [conflict.id],
          );
          const model = (
            await c.query('SELECT model_id FROM vehicles WHERE id=$1', [input.vehicleId])
          ).rows[0].model_id;
          const changed = (
            await c.query(
              `UPDATE bookings SET version=version+1,updated_at=now(),
                  target_type=CASE WHEN target_type='vehicle' THEN 'model' ELSE target_type END,
                  target_model_id=CASE WHEN target_type='vehicle' THEN $2 ELSE target_model_id END,target_vehicle_id=NULL WHERE id=$1 RETURNING *`,
              [b.id, model],
            )
          ).rows[0];
          if (b.target_type === 'vehicle')
            await this.s.reviseTarget(
              c,
              b.id,
              changed.version,
              { type: 'model', id: model },
              input.reason,
              r.auth!.user.id,
            );
          // The relation is recorded after the block exists below.
        }
        const row = blockId
          ? (
              await c.query(
                'UPDATE schedule_blocks SET start_at=$2,end_at=$3,reason=$4,version=version+1 WHERE id=$1 RETURNING *',
                [blockId, input.startAt, input.endAt, input.reason],
              )
            ).rows[0]
          : (
              await c.query(
                "INSERT INTO schedule_blocks(vehicle_id,kind,start_at,end_at,reason,created_by) VALUES ($1,'technical',$2,$3,$4,$5) RETURNING *",
                [input.vehicleId, input.startAt, input.endAt, input.reason, r.auth!.user.id],
              )
            ).rows[0];
        for (const conflict of affected)
          await this.s.event(
            c,
            r,
            'booking',
            conflict.booking_id,
            conflict.booking_version + 1,
            'bookings.displaced',
            { reason: input.reason, previousVehicleId: input.vehicleId, technicalBlockId: row.id },
          );
        await this.s.event(
          c,
          r,
          'schedule_block',
          row.id,
          row.version,
          blockId ? 'schedule.updated' : 'schedule.created',
          { reason: input.reason, displacedBookings: expected.map((x) => x.id) },
        );
        return row;
      },
      false,
    );
  }
  @Post('schedule-blocks/:id/cancel')
  cancelTechnical(
    @Param('id')
    raw: string,
    @Body()
    body: unknown,
    @Req()
    r: AuthRequest,
  ) {
    const blockId = parse(idSchema, raw),
      input = parse(version, body);
    return this.s.commands.run(
      r,
      'schedule.cancel',
      { blockId, ...input },
      async (c) => {
        await scheduleLock(c);
        const row = (
          await c.query(
            "UPDATE schedule_blocks SET retired_at=now(),version=version+1 WHERE id=$1 AND version=$2 AND kind='technical' AND retired_at IS NULL RETURNING *",
            [blockId, input.expectedVersion],
          )
        ).rows[0];
        if (!row) fail(409, 'VERSION_CONFLICT', 'Блокировка изменилась. Обновите данные.');
        await this.s.event(c, r, 'schedule_block', blockId, row.version, 'schedule.cancelled', {
          reason: input.reason,
        });
        return row;
      },
      false,
    );
  }
  @Get('booking-targets')
  async targets(
    @Query()
    raw: unknown,
  ) {
    const q = parse(z.object({ q: z.string().max(100).default('') }).strict(), raw).q;
    const items = (
      await this.s.db.pool
        .query(`SELECT 'vehicle' AS type,v.id,b.name||' '||m.name||' · '||v.plate AS label FROM vehicles v JOIN vehicle_models m ON m.id=v.model_id JOIN vehicle_brands b ON b.id=m.brand_id WHERE v.archived_at IS NULL
      UNION ALL SELECT 'model',m.id,b.name||' '||m.name FROM vehicle_models m JOIN vehicle_brands b ON b.id=m.brand_id
      UNION ALL SELECT 'brand',id,name FROM vehicle_brands UNION ALL SELECT 'equivalence_group',id,name FROM equivalence_groups`)
    ).rows;
    return { items: items.filter((i) => i.label.toLowerCase().includes(q.toLowerCase())) };
  }
  @Post('availability/evaluate')
  async evaluate(
    @Body()
    raw: unknown,
  ) {
    const input = parse(evaluation, raw);
    return this.s.db.transaction(async (c) => {
      await c.query('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');
      const old = input.bookingId
        ? (await c.query('SELECT * FROM bookings WHERE id=$1', [input.bookingId])).rows[0]
        : undefined;
      if (input.bookingId && !old) fail(404, 'NOT_FOUND', 'Бронь не найдена.');
      const same =
        old &&
        old.target_type === input.target.type &&
        (old.target_vehicle_id ??
          old.target_model_id ??
          old.target_brand_id ??
          old.target_group_id) === input.target.id;
      const models = same
        ? (
            await c.query(
              'SELECT model_id FROM booking_eligible_models WHERE booking_id=$1 ORDER BY model_id',
              [old.id],
            )
          ).rows.map((x) => x.model_id)
        : await this.s.models(c, input.target);
      const inspection = await this.s.inspect(c, {
        id: input.bookingId,
        target: input.target,
        models,
        startAt: input.startAt,
        endAt: input.endAt,
        vehicleId: input.target.type === 'vehicle' ? input.target.id : input.vehicleId,
      });
      return { ...inspection.availability, ...inspection };
    });
  }
  @Get('bookings/:id')
  async get(
    @Param('id')
    raw: string,
  ) {
    const booking = (
      await this.s.db.pool.query(
        `SELECT b.*,c.display_name AS customer_name,s.vehicle_id FROM bookings b JOIN customers c ON c.id=b.customer_id LEFT JOIN schedule_blocks s ON s.booking_id=b.id AND s.retired_at IS NULL WHERE b.id=$1`,
        [parse(idSchema, raw)],
      )
    ).rows[0];
    if (!booking) fail(404, 'NOT_FOUND', 'Бронь не найдена.');
    const inspection = await this.s.db.transaction(async (c) => {
      await c.query('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');
      const models = (
        await c.query('SELECT model_id FROM booking_eligible_models WHERE booking_id=$1', [
          booking.id,
        ])
      ).rows.map((x) => x.model_id);
      return this.s.inspect(c, {
        id: booking.id,
        target: {
          type: booking.target_type,
          id:
            booking.target_vehicle_id ??
            booking.target_model_id ??
            booking.target_brand_id ??
            booking.target_group_id,
        },
        models,
        startAt: booking.start_at.toISOString(),
        endAt: booking.end_at.toISOString(),
        vehicleId: booking.vehicle_id,
      });
    });
    const vehicleOptions = (
      await this.s.db.pool.query(
        `SELECT v.id,v.model_id AS "modelId",m.pricing_group_id AS "pricingGroupId",v.is_ready AS "isReady",EXISTS(SELECT 1 FROM schedule_blocks s WHERE s.vehicle_id=v.id AND s.retired_at IS NULL AND (s.booking_id IS NULL OR s.booking_id<>$1) AND s.start_at<b.end_at AND s.end_at>b.start_at) AS busy FROM vehicles v JOIN vehicle_models m ON m.id=v.model_id CROSS JOIN bookings b WHERE b.id=$1 AND v.archived_at IS NULL`,
        [booking.id],
      )
    ).rows;
    return {
      ...booking,
      ...inspection,
      vehicleOptions,
      terms: (
        await this.s.db.pool.query(
          'SELECT * FROM booking_terms WHERE booking_id=$1 ORDER BY revision DESC',
          [booking.id],
        )
      ).rows,
      risks: (
        await this.s.db.pool.query('SELECT * FROM booking_risks WHERE booking_id=$1 ORDER BY id', [
          booking.id,
        ])
      ).rows,
    };
  }
  @Get('bookings/:id/history')
  async history(
    @Param('id')
    raw: string,
  ) {
    const items = (
      await this.s.db.pool.query(
        'SELECT a.id,a.action,a.details,a.created_at AS "createdAt",u.full_name AS author FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id WHERE a.entity_type=\'booking\' AND a.entity_id=$1 ORDER BY a.id DESC LIMIT 100',
        [parse(idSchema, raw)],
      )
    ).rows;
    const terms = (
      await this.s.db.pool.query(
        `SELECT t.id,t.revision,t.snapshot->>'finalTotalRub' AS "priceRub",t.reason,t.created_at AS "createdAt",u.full_name AS author FROM booking_terms t LEFT JOIN users u ON u.id=t.created_by WHERE t.booking_id=$1 ORDER BY t.revision DESC`,
        [parse(idSchema, raw)],
      )
    ).rows;
    return { items, total: items.length, terms };
  }
  @Post('bookings')
  create(
    @Body()
    raw: unknown,
    @Req()
    r: AuthRequest,
  ) {
    return this.bookings.create(parse(create, raw), r);
  }
  @Patch('bookings/:id/terms')
  update(
    @Param('id')
    raw: string,
    @Body()
    body: unknown,
    @Req()
    r: AuthRequest,
  ) {
    return this.bookings.update(parse(change, body), r, parse(idSchema, raw));
  }
  private async inspectMove(
    c: PoolClient,
    bookingId: number,
    startAt: string,
    vehicleId: number,
    actor: number,
  ) {
    const b = (
      await c.query(
        `SELECT b.*,s.vehicle_id, t.snapshot FROM bookings b LEFT JOIN schedule_blocks s ON s.booking_id=b.id AND s.retired_at IS NULL JOIN LATERAL (SELECT snapshot FROM booking_terms WHERE booking_id=b.id ORDER BY revision DESC LIMIT 1) t ON true WHERE b.id=$1`,
        [bookingId],
      )
    ).rows[0];
    if (!b || b.status !== 'confirmed') fail(404, 'NOT_FOUND', 'Подтверждённая бронь не найдена.');
    if (b.snapshot.operationKind !== 'initial')
      fail(422, 'MOVE_UNSUPPORTED', 'Перенос этой брони требует редактирования условий.');
    const models = (
      await c.query('SELECT model_id FROM booking_eligible_models WHERE booking_id=$1', [bookingId])
    ).rows.map((x) => x.model_id);
    const v = (
      await c.query(
        'SELECT v.id,v.model_id,v.plate,v.is_ready,v.archived_at,m.pricing_group_id FROM vehicles v JOIN vehicle_models m ON m.id=v.model_id WHERE v.id=$1',
        [vehicleId],
      )
    ).rows[0];
    if (!v || v.archived_at) fail(404, 'NOT_FOUND', 'Автомобиль не найден.');
    const endAt = new Date(
      Date.parse(startAt) + (Date.parse(b.end_at) - Date.parse(b.start_at)),
    ).toISOString();
    const changedModel = !models.includes(v.model_id);
    const target =
      changedModel || b.target_type === 'vehicle'
        ? { type: 'vehicle' as const, id: vehicleId }
        : { type: b.target_type, id: b.target_model_id ?? b.target_brand_id ?? b.target_group_id };
    const nextModels = changedModel ? [v.model_id] : models;
    const changedTariff = v.pricing_group_id !== b.snapshot.periods[0]?.pricingGroup?.id;
    let quote: Awaited<ReturnType<typeof previewBooking>> | undefined;
    if (changedTariff) {
      const source: Partial<NonNullable<Calculation['overrides']>> =
        (b.snapshot as Calculation).overrides ?? {};
      const overrides: Partial<NonNullable<Calculation['overrides']>> = {};
      for (const key of [
        'customDailyRateRub',
        'mileageLimitKm',
        'discountRub',
        'discountBps',
      ] as const)
        if (source[key] !== undefined) Object.assign(overrides, { [key]: source[key] });
      if (Object.keys(overrides).length)
        overrides.reason = source.reason || 'Ранее согласованные индивидуальные условия';
      const pricing: z.infer<typeof bookingPricing> = {
        startAt,
        contractDays: b.snapshot.contractDays,
        dailyMileagePackageKm: b.snapshot.dailyMileagePackageKm,
        ...(Object.keys(overrides).length
          ? { overrides: overrides as NonNullable<Calculation['overrides']> }
          : {}),
        ...(b.snapshot.nonBillableDays?.length
          ? {
              nonBillableDays: b.snapshot.nonBillableDays.map(
                (d: Calculation['nonBillableDays'][number]) => ({
                  dayIndex: d.dayIndex,
                  reason: d.reason,
                }),
              ),
            }
          : {}),
      };
      quote = await previewBooking(c, target, pricing, nextModels, actor);
    }
    const inspection = await this.s.inspect(c, {
      id: bookingId,
      target,
      models: nextModels,
      startAt,
      endAt,
      vehicleId,
    });
    const blocked = !v.is_ready || inspection.conflicts.length > 0;
    return {
      ...inspection,
      booking: b,
      vehicle: v,
      startAt,
      endAt,
      vehicleId,
      blocked,
      models: nextModels,
      target,
      changedModel,
      changedTariff,
      quote,
    };
  }
  @Post('bookings/:id/move/preview')
  async previewMove(@Param('id') raw: string, @Body() body: unknown, @Req() r: AuthRequest) {
    const bookingId = parse(idSchema, raw),
      input = parse(
        z.object({ startAt: z.iso.datetime({ offset: true }), vehicleId: id }).strict(),
        body,
      );
    return this.s.db.transaction(async (c) => {
      await c.query('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');
      const p = await this.inspectMove(
        c,
        bookingId,
        input.startAt,
        input.vehicleId,
        r.auth!.user.id,
      );
      return {
        bookingId,
        expectedVersion: p.booking.version,
        oldStartAt: p.booking.start_at,
        oldEndAt: p.booking.end_at,
        oldVehicleId: p.booking.vehicle_id,
        oldPriceRub: p.booking.snapshot.finalTotalRub,
        startAt: p.startAt,
        endAt: p.endAt,
        vehicleId: p.vehicleId,
        vehiclePlate: p.vehicle.plate,
        priceRub: p.quote?.calculation.finalTotalRub ?? p.booking.snapshot.finalTotalRub,
        quoteToken: p.quote?.previewToken,
        changedModel: p.changedModel,
        blocked: p.blocked,
        conflicts: p.conflicts,
        availability: p.availability,
      };
    });
  }
  @Post('bookings/:id/move')
  move(@Param('id') raw: string, @Body() body: unknown, @Req() r: AuthRequest) {
    const bookingId = parse(idSchema, raw),
      input = parse(moveInput, body);
    return this.s.commands.run(
      r,
      'bookings.move',
      { bookingId, ...input },
      async (c) => {
        await scheduleLock(c);
        const p = await this.inspectMove(
          c,
          bookingId,
          input.startAt,
          input.vehicleId,
          r.auth!.user.id,
        );
        if (p.booking.version !== input.expectedVersion)
          fail(409, 'BOOKING_VERSION_CONFLICT', 'Бронь изменилась. Проверьте перенос снова.');
        if (p.blocked)
          fail(
            409,
            'VEHICLE_ASSIGNMENT_CONFLICT',
            'Выбранный автомобиль недоступен на этот период.',
            { conflicts: p.conflicts },
          );
        if (p.availability.token !== input.availabilityToken)
          fail(409, 'MOVE_PREVIEW_STALE', 'Расписание изменилось. Проверьте перенос снова.');
        if (p.quote?.previewToken !== input.quoteToken)
          fail(409, 'MOVE_PREVIEW_STALE', 'Стоимость изменилась. Проверьте перенос снова.');
        if (
          p.booking.vehicle_id === input.vehicleId &&
          Date.parse(p.booking.start_at) === Date.parse(input.startAt)
        )
          fail(422, 'MOVE_UNCHANGED', 'Бронь не перемещена.');
        const delta = Date.parse(input.startAt) - Date.parse(p.booking.start_at);
        const shift = (value: string) => new Date(Date.parse(value) + delta).toISOString();
        const old = p.booking.snapshot as Calculation;
        const snapshot = p.quote
          ? { ...p.quote.calculation, target: p.target, eligibleModels: p.models }
          : {
              ...old,
              startAt: p.startAt,
              agreedReturnAt: p.endAt,
              target: p.target,
              eligibleModels: p.models,
              periods: old.periods?.map((item) => ({
                ...item,
                startsAt: shift(item.startsAt),
                endsAt: shift(item.endsAt),
              })),
              dayLines: old.dayLines?.map((item) => ({
                ...item,
                startAt: shift(item.startAt),
                endAt: shift(item.endAt),
              })),
              ...(old.pricingBasis
                ? {
                    pricingBasis: {
                      ...old.pricingBasis,
                      startsAt: shift(old.pricingBasis.startsAt),
                      endsAt: shift(old.pricingBasis.endsAt),
                    },
                  }
                : {}),
            };
        let quoteId: number | undefined;
        if (p.quote) {
          const quote = (
            await c.query(
              `INSERT INTO pricing_quotes(created_by,confirmed_by,expires_at,confirmed_at,version,input,snapshot,confirmed_overrides) VALUES ($1,$1,now()+interval '30 minutes',now(),2,$2,$3,$4) RETURNING id`,
              [
                r.auth!.user.id,
                JSON.stringify(p.quote.input),
                JSON.stringify(p.quote.calculation),
                JSON.stringify(p.quote.calculation.overridesToConfirm),
              ],
            )
          ).rows[0];
          quoteId = quote.id;
          await audit(
            c,
            r.auth!.user.id,
            'pricing_quote',
            'pricing.confirmed',
            quoteId!,
            r.requestId,
            { context: 'booking_move', confirmedOverrides: p.quote.calculation.overridesToConfirm },
          );
          await c.query('INSERT INTO outbox_jobs(business_key,kind,payload) VALUES ($1,$2,$3)', [
            'pricing.confirmed:' + quoteId,
            'pricing.confirmed',
            JSON.stringify({ id: quoteId, version: 2 }),
          ]);
        }
        await c.query(
          'UPDATE schedule_blocks SET retired_at=now() WHERE booking_id=$1 AND retired_at IS NULL',
          [bookingId],
        );
        const row = (
          await c.query(
            `UPDATE bookings SET start_at=$2,end_at=$3,target_type=$4,target_vehicle_id=$5,target_model_id=$6,target_brand_id=$7,target_group_id=$8,version=version+1,updated_at=now() WHERE id=$1 RETURNING *`,
            [
              bookingId,
              p.startAt,
              p.endAt,
              p.target.type,
              p.target.type === 'vehicle' ? p.target.id : null,
              p.target.type === 'model' ? p.target.id : null,
              p.target.type === 'brand' ? p.target.id : null,
              p.target.type === 'equivalence_group' ? p.target.id : null,
            ],
          )
        ).rows[0];
        if (p.changedModel) {
          await c.query('DELETE FROM booking_eligible_models WHERE booking_id=$1', [bookingId]);
          await c.query('INSERT INTO booking_eligible_models(booking_id,model_id) VALUES ($1,$2)', [
            bookingId,
            p.vehicle.model_id,
          ]);
        }
        await this.s.assignment(
          c,
          bookingId,
          input.vehicleId,
          p.startAt,
          p.endAt,
          r.auth!.user.id,
          input.reason,
        );
        await c.query(
          `INSERT INTO booking_terms(booking_id,revision,quote_id,snapshot,reason,created_by) SELECT booking_id,$2,coalesce($3,quote_id),$4,$5,$6 FROM booking_terms WHERE booking_id=$1 ORDER BY revision DESC LIMIT 1`,
          [
            bookingId,
            row.version,
            quoteId ?? null,
            JSON.stringify(snapshot),
            input.reason,
            r.auth!.user.id,
          ],
        );
        if (p.availability.status !== 'feasible')
          await c.query(
            'INSERT INTO booking_risks(booking_id,snapshot,reason,created_by) VALUES ($1,$2,$3,$4)',
            [
              bookingId,
              JSON.stringify(p.availability),
              'Перенос брони при неполной доступности автопарка',
              r.auth!.user.id,
            ],
          );
        await this.s.event(c, r, 'booking', bookingId, row.version, 'bookings.moved', {
          previousVehicleId: p.booking.vehicle_id,
          vehicleId: input.vehicleId,
          previousStartAt: p.booking.start_at,
          startAt: p.startAt,
          previousPriceRub: old.finalTotalRub,
          priceRub: snapshot.finalTotalRub,
          reason: input.reason,
          ...(p.availability.status !== 'feasible'
            ? { availabilityStatus: p.availability.status }
            : {}),
        });
        return row;
      },
      false,
    );
  }
  @Post('bookings/:id/assign-vehicle')
  assignment(
    @Param('id')
    raw: string,
    @Body()
    body: unknown,
    @Req()
    r: AuthRequest,
  ) {
    const bookingId = parse(idSchema, raw);
    const input = parse(assignVehicle, body);
    return this.bookings.assign(input, r, bookingId);
  }
  @Post('bookings/:id/cancel')
  cancel(
    @Param('id')
    raw: string,
    @Body()
    body: unknown,
    @Req()
    r: AuthRequest,
  ) {
    const bookingId = parse(idSchema, raw);
    const input = parse(cancelBooking, body);
    return this.bookings.cancel(input, r, bookingId);
  }
}
